<?php $this->setLayout(''); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NairaBill Admin Sign In</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f4f8f4;font:15px system-ui;color:#173329}.card{width:min(420px,calc(100% - 32px));background:#fff;border:1px solid #dfe9e1;border-radius:18px;padding:30px;box-shadow:0 20px 60px #143e2810}.brand{font-size:26px;font-weight:850;margin-bottom:8px}.brand span{color:#147d58}label{display:block;font-weight:650;margin:16px 0 6px}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #d7e2da;border-radius:9px;font:inherit}button{margin-top:22px;width:100%;padding:12px;background:#147d58;color:white;border:0;border-radius:9px;font-weight:750;font:inherit;cursor:pointer}.error{padding:10px;background:#fff0ed;color:#9b3d2e;border-radius:8px}</style></head><body><form class="card" method="post" action="/admin/login"><div class="brand">Naira<span>Bill</span></div><p>Platform administrator sign in</p><?php if(!empty($error)): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><label for="email">Admin email</label><input id="email" type="email" name="email" required autocomplete="username"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password"><button type="submit">Sign in securely</button></form></body></html>
